class Solution {
public:
    bool canBeValid(string s, string locked) {
        int n = s.size();
        if (n % 2 == 1) return false;

        // Left-to-right: treat unlocked as '(', locked ')' as decrement
        int balance = 0;
        for (int i = 0; i < n; i++) {
            if (locked[i] == '1' && s[i] == ')') {
                balance--;
            } else {
                balance++;
            }
            if (balance < 0) return false;
        }

        // Right-to-left: treat unlocked as ')', locked '(' as decrement
        balance = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (locked[i] == '1' && s[i] == '(') {
                balance--;
            } else {
                balance++;
            }
            if (balance < 0) return false;
        }

        return true;
    }
};
